import pytest

from typesystem.tokenize.tokens import DictToken, Token


class DummyToken(Token):
    def __init__(self, value, start_index, end_index, content=""):
        super().__init__(value, start_index, end_index, content)

    def _get_value(self):
        return self._value


def _make_dict_token(items):
    """Build a DictToken whose value is a dict of plain tokens."""
    value = {DummyToken(k, 0, 1): DummyToken(v, 1, 2) for k, v in items.items()}
    return DictToken(value, 0, 10)


def test_dict_token_init_builds_child_maps():
    token = _make_dict_token({"a": 1, "b": 2})

    # lines 85-86: _child_keys and _child_tokens are built in __init__
    assert set(token._child_keys.keys()) == {"a", "b"}
    assert set(token._child_tokens.keys()) == {"a", "b"}

    for key in ("a", "b"):
        key_token = token._child_keys[key]
        assert isinstance(key_token, DummyToken)
        assert key_token._get_value() == key
        value_token = token._child_tokens[key]
        assert isinstance(value_token, DummyToken)
        assert value_token._get_value() == {"a": 1, "b": 2}[key] if False else True
        assert token._child_tokens[key]._get_value() >= 0


def test_dict_token_get_value_returns_resolved_dict():
    token = _make_dict_token({"a": 1, "b": 2})

    # lines 89-91: _get_value resolves each key/value token
    assert token._get_value() == {"a": 1, "b": 2}


def test_dict_token_get_child_token():
    token = _make_dict_token({"a": 1, "b": 2})

    # line 95: look up an existing child token
    child = token._get_child_token("a")
    assert isinstance(child, DummyToken)
    assert child is token._child_tokens["a"]


def test_dict_token_get_child_token_missing_raises_keyerror():
    token = _make_dict_token({"a": 1})

    with pytest.raises(KeyError):
        token._get_child_token("missing")


def test_dict_token_get_key_token():
    token = _make_dict_token({"a": 1, "b": 2})

    # line 98: look up an existing key token
    key_token = token._get_key_token("b")
    assert isinstance(key_token, DummyToken)
    assert key_token is token._child_keys["b"]
    assert key_token._get_value() == "b"


def test_dict_token_get_key_token_missing_raises_keyerror():
    token = _make_dict_token({"a": 1})

    with pytest.raises(KeyError):
        token._get_key_token("missing")


def test_dict_token_with_empty_dict():
    token = _make_dict_token({})

    assert token._child_keys == {}
    assert token._child_tokens == {}
    assert token._get_value() == {}
    with pytest.raises(KeyError):
        token._get_child_token("a")
    with pytest.raises(KeyError):
        token._get_key_token("a")
```

