Validation plan: build a dict-like node containing a key token, another dict-like node nested under a list index, and a standalone key token, and assert that `lookup_key` traverses to the right node and returns key tokens whose `.value` matches the expected key. If traversal or key lookup were broken, the returned token's `value` would be `None` and the assert would fail.

```python
from typesystem.tokenize.tokens import Token


class _LeafKeyToken(Token):
    """A terminal token that plays the role of a dictionary key token."""

    def _get_child_token(self, key):
        return None

    def _get_key_token(self, key):
        return _LeafKeyToken(key)


class _DictLikeToken(Token):
    """A dict-like container token mapping key -> token."""

    def _get_child_token(self, key):
        return self._mapping[key]

    def _get_key_token(self, key):
        return self._mapping[key]


class _ListLikeToken(Token):
    """A list-like container token mapping int index -> token."""

    def _get_child_token(self, key):
        return self._items[key]

    def _get_key_token(self, key):
        return self._items[key]


def test_lookup_key_via_dict_like_token():
    key_token = _LeafKeyToken("colour")
    root = _DictLikeToken()
    root._mapping = {"inner": key_token}

    result = root.lookup_key([None, "inner"])

    assert result is key_token
    assert result.value == "colour"


def test_lookup_key_via_list_like_token():
    key_token = _LeafKeyToken(42)
    root = _ListLikeToken()
    root._items = ["unused", key_token]

    result = root.lookup_key([-1, 1])

    assert result is key_token
    assert result.value == 42
