from typesystem.tokenize.tokens import Token


class _LeafKeyToken(Token):
    """A terminal token that plays the role of a dictionary key token."""

    def _get_child_token(self, key):
        return None

    def _get_key_token(self, key):
        return _LeafKeyToken(key, 0, 0)


class _DictLikeToken(Token):
    """A dict-like container token mapping key -> token."""

    def _get_child_token(self, key):
        return self._mapping[key]

    def _get_key_token(self, key):
        return self._mapping[key]


class _ListLikeToken(Token):
    """A list-like container token mapping int index -> token."""

    def _get_child_token(self, key):
        return self._items[key]

    def _get_key_token(self, key):
        return self._items[key]


def test_lookup_key_via_dict_like_token():
    key_token = _LeafKeyToken("colour", 0, 6)
    inner_dict_token = _DictLikeToken("inner", 0, 10)
    inner_dict_token._mapping = {"colour": key_token}
    root = _DictLikeToken("root", 0, 20)
    root._mapping = {"inner": inner_dict_token}

    result = root.lookup_key([None, "inner", "colour"])

    # index[:-1] = [None, "inner"] navigates root -> inner_dict_token,
    # then _get_key_token("colour") is invoked on it.
    assert result is key_token
    assert result.value == "colour"


def test_lookup_key_via_list_like_token():
    key_token = _LeafKeyToken(42, 0, 2)
    root = _ListLikeToken([key_token], 0, 10)
    root._items = [key_token]

    result = root.lookup_key([0])

    # index[:-1] = [] navigates to root itself,
    # then _get_key_token(0) is invoked on it.
    assert result is key_token
    assert result.value == 42
```

